const rows = $input.all().map((item) => item.json ?? {});
const config = $('Configure Search').first().json ?? {};
const keywords = Array.isArray(config.keywords)
  ? [...new Set(config.keywords.map((value) => String(value ?? '').normalize('NFKC').trim().toLowerCase()).filter(Boolean))]
  : [];

const cleanCell = (value) => {
  const normalized = String(value ?? '').normalize('NFKC').replace(/[\r\n\t]+/g, ' ').replace(/\s{2,}/g, ' ').trim();
  return /^[=+\-@]/.test(normalized) ? `'${normalized}` : normalized;
};

const leads = [];
const seen = new Set();
for (const row of rows) {
  if (row.found !== true || row.attributionConfirmed !== true) continue;
  const title = cleanCell(row.title);
  const jobUrl = cleanCell(row.url);
  if (!title || !/^https?:\/\//i.test(jobUrl)) continue;
  const haystack = `${row.title ?? ''} ${row.department ?? ''}`.normalize('NFKC').toLowerCase();
  const matched = keywords.filter((keyword) => haystack.includes(keyword));
  if (keywords.length > 0 && matched.length === 0) continue;
  const companyDomain = cleanCell(row.companyDomain);
  const dedupeKey = `${companyDomain.toLowerCase()}\u0000${jobUrl}`;
  if (seen.has(dedupeKey)) continue;
  seen.add(dedupeKey);
  leads.push({
    status: 'lead',
    companyDomain,
    title,
    department: cleanCell(row.department),
    location: cleanCell(row.location),
    isRemote: typeof row.isRemote === 'boolean' ? row.isRemote : '',
    jobUrl,
    publishedAt: cleanCell(row.publishedAt),
    atsProvider: cleanCell(row.provider),
    matchedKeywords: cleanCell(matched.join('|')),
    scrapedAt: cleanCell(row.scrapedAt),
  });
}

leads.sort((a, b) => a.companyDomain.localeCompare(b.companyDomain) || a.title.localeCompare(b.title) || a.jobUrl.localeCompare(b.jobUrl));
if (leads.length === 0) {
  const latestScrapedAt = rows.map((row) => cleanCell(row.scrapedAt)).filter(Boolean).sort().at(-1) ?? '';
  leads.push({
    status: 'no_matching_jobs',
    companyDomain: '',
    title: '',
    department: '',
    location: '',
    isRemote: '',
    jobUrl: '',
    publishedAt: '',
    atsProvider: '',
    matchedKeywords: '',
    scrapedAt: latestScrapedAt,
  });
}

return leads.map((json) => ({ json }));
